cd /workspace && node -e "
const db = require('better-sqlite3')('world.db');
// List all product types from the retail skill
const products = db.prepare(\"SELECT * FROM products WHERE source_skill='tau2Retail'\").all();
console.log('Total products:', products.length);
// Search for anything mouse-related
const mouseProducts = products.filter(p => p.name.toLowerCase().includes('mouse'));
console.log('Mouse products:', mouseProducts);
// Also search more broadly
const logitechProducts = products.filter(p => p.name.toLowerCase().includes('logi'));
console.log('Logitech products:', logitechProducts);
// Show all product names
console.log('All product names:');
products.forEach(p => console.log(' -', p.name, '(id:', p.product_id + ')'));
"
